      "path": "lib/local.js",
      "content": "/**
 * dsh-plugin-local-life — pure local-life helpers: budgets, bill splitting,
 * unit prices, discounts, unit conversions, trip checklists.
 *
 * No DSH or Cordis imports here, so this module is unit-testable in
 * isolation. The model talks to the user; these helpers do the arithmetic.
 */

function round2(v) {
  return Math.round((v + Number.EPSILON) * 100) / 100;
}

/** Monthly budget plan: allocate income across categories. */
export function budgetPlan({ income = 0, items = [], savingsPct = 0 } = {}) {
  const inc = Number(income);
  if (!Number.isFinite(inc) || inc < 0) throw new Error("local: income must be a non-negative number");
  const list = Array.isArray(items) ? items.filter((x) => x && x.name) : [];
  const allocated = [];
  let used = 0;
  for (const it of list) {
    let amount;
    if (typeof it.amount === "number" && Number.isFinite(it.amount)) {
      amount = it.amount;
    } else if (typeof it.pct === "number" && Number.isFinite(it.pct)) {
      amount = (inc * it.pct) / 100;
    } else {
      throw new Error("local: each budget item needs amount or pct");
    }
    if (amount < 0) throw new Error("local: budget item amounts must be non-negative");
    allocated.push({ name: it.name, amount: round2(amount) });
    used += amount;
  }
  const savings = (inc * Number(savingsPct || 0)) / 100;
  const leftover = inc - used - savings;
  return {
    income: inc,
    savings: round2(savings),
    items: allocated,
    allocatedTotal: round2(used),
    leftover: round2(leftover),
    balanced: leftover >= 0,
    text: [
      "Income: " + inc,
      "Savings target: " + round2(savings),
      ...allocated.map((a) => "- " + a.name + ": " + a.amount),
      "Allocated total: " + round2(used),
      "Leftover: " + round2(leftover) + (leftover >= 0 ? "" : " (over budget!)"),
    ].join("\n"),
  };
}

/** Split a bill N ways with optional weights and tip. */
export function splitBill({ total = 0, people = 2, weights = [], tipPct = 0, roundTo } = {}) {
  const t = Number(total);
  const n = Math.max(1, Math.floor(people));
  const tip = Number(tipPct || 0);
  if (!Number.isFinite(t) || t < 0) throw new Error("local: total must be a non-negative number");
  if (tip < 0) throw new Error("local: tipPct must be non-negative");
  const grand = t * (1 + tip / 100);
  let shares;
  if (Array.isArray(weights) && weights.length === n && weights.every((w) => Number(w) > 0)) {
    const sum = weights.reduce((a, w) => a + Number(w), 0);
    shares = weights.map((w) => (grand * Number(w)) / sum);
  } else {
    shares = Array.from({ length: n }, () => grand / n);
  }
  const rounded = shares.map((s) => (roundTo == null ? round2(s) : Math.ceil((s - 1e-9) / roundTo) * roundTo));
  const sum = rounded.reduce((a, b) => a + b, 0);
  const adjustment = roundTo == null ? round2(sum - grand) : round2(grand - sum);
  if (roundTo == null && Math.abs(adjustment) > 0.01) {
    rounded[n - 1] = round2(rounded[n - 1] - adjustment);
  }
  return {
    total: t,
    tipPct: tip,
    grandTotal: round2(grand),
    people: n,
    shares: rounded,
    sharesSum: round2(rounded.reduce((a, b) => a + b, 0)),
    text: [
      "Bill: " + t + (tip > 0 ? " + " + tip + "% tip" : "") + " = " + round2(grand),
      ...rounded.map((s, i) => "- Person " + (i + 1) + ": " + s),
      "Sum: " + round2(rounded.reduce((a, b) => a + b, 0)),
    ].join("\n"),
  };
}

const UNIT_FACTORS = {
  weight: { g: 1, kg: 1000, 克: 1, 公斤: 1000, 千克: 1000, 斤: 500, 磅: 453.59237, oz: 28.349523 },
  volume: { ml: 1, L: 1000, 升: 1000, 毫升: 1, 加仑: 3785.411784, gallon: 3785.411784, cup: 236.588 },
  length: { m: 1, km: 1000, cm: 0.01, 米: 1, 公里: 1000, 千米: 1000, 里: 500, 尺: 0.333333, 英里: 1609.344, mile: 1609.344, ft: 0.3048 },
};

/** Unit price: normalize an amount to price-per-comparison-unit. */
export function unitPrice({ price = 0, amount = 0, amountUnit = "g", compareUnit = "kg" } = {}) {
  const p = Number(price);
  const a = Number(amount);
  if (!Number.isFinite(p) || !Number.isFinite(a) || a <= 0) throw new Error("local: price and positive amount required");
  let factor = null;
  for (const table of Object.values(UNIT_FACTORS)) {
    if (amountUnit in table && compareUnit in table) {
      factor = table[compareUnit] / table[amountUnit];
      break;
    }
  }
  if (factor === null) throw new Error("local: unsupported units '" + amountUnit + "' -> '" + compareUnit + "'");
  const per = (p / a) * factor;
  return { unitPrice: round2(per), perUnit: compareUnit, text: p + " / " + a + amountUnit + " = " + round2(per) + " per " + compareUnit };
}

/** Discount math: percent-off, amount-off with threshold, savings. */
export function discount({ price = 0, offPct, offAmount, threshold } = {}) {
  const p = Number(price);
  if (!Number.isFinite(p) || p < 0) throw new Error("local: price must be a non-negative number");
  let final = p;
  let note = "";
  if (offAmount != null && Number.isFinite(Number(offAmount))) {
    if (threshold != null && p < Number(threshold)) note = " (threshold " + threshold + " not met — no discount)";
    else final = p - Number(offAmount);
  } else if (offPct != null && Number.isFinite(Number(offPct))) {
    if (offPct < 0 || offPct > 100) throw new Error("local: offPct must be between 0 and 100");
    final = p * (1 - Number(offPct) / 100);
    note = " (" + offPct + "% off)";
  }
  final = Math.max(0, round2(final));
  return { original: p, final, savings: round2(p - final), note: note.trim(), text: p + " -> " + final + note };
}

const TEMP = {
  toBase: { c: (v) => v, f: (v) => (v - 32) * 5 / 9 },
  fromBase: { c: (v) => v, f: (v) => v * 9 / 5 + 32 },
};

/** Convert between supported units (weight/length/volume/temperature). */
export function unitConvert({ value = 0, from = "kg", to = "斤" } = {}) {
  const v = Number(value);
  if (!Number.isFinite(v)) throw new Error("local: value must be a finite number");
  const f = String(from).toLowerCase();
  const t = String(to).toLowerCase();
  if (f === t) return { value: v, from, to, text: v + " " + from };
  for (const table of Object.values(UNIT_FACTORS)) {
    if (f in table && t in table) {
      const out = (v * table[f]) / table[t];
      return { value: round2(out), from, to, text: v + " " + from + " = " + round2(out) + " " + to };
    }
  }
  const tc = f.replace(/°?celsius?|摄氏/g, "c").replace(/°?fahrenheit?|华氏/g, "f");
  const tt = t.replace(/°?celsius?|摄氏/g, "c").replace(/°?fahrenheit?|华氏/g, "f");
  if (tc in TEMP.toBase && tt in TEMP.fromBase) {
    const out = TEMP.fromBase[tt](TEMP.toBase[tc](v));
    return { value: round2(out), from, to, text: v + " " + from + " = " + round2(out) + " " + to };
  }
  throw new Error("local: unsupported conversion '" + from + "' -> '" + to + "'");
}

const TRIP_LISTS = {
  city: ["ID / passport", "Phone charger + power bank", "Transport app / metro card", "Hotel confirmation", "Comfortable shoes", "Umbrella or rain gear", "Local SIM / eSIM or roaming plan"],
  airport: ["Passport / ID", "Boarding pass (or check-in code)", "Visa / entry documents", "Liquids under 100ml in clear bag", "Power bank in carry-on", "Chargers + adapter", "Arrival transport plan"],
  outdoor: ["Weather check + layered clothing", "Water (2L+) and snacks", "Navigation (offline map / GPS)", "First-aid kit", "Sun protection (hat, sunscreen)", "Flashlight / headlamp", "Tell someone your route"],
  selfdrive: ["License + registration + insurance", "Full tank / charge plan", "Tire pressure check", "Navigation + offline map", "Emergency kit (jack, triangle)", "Cash / toll card", "Rest stops planned"],
};

/** Trip/outing checklist by scenario. */
export function tripChecklist({ scenario = "city" } = {}) {
  const list = TRIP_LISTS[scenario] ?? TRIP_LISTS.city;
  return "Trip checklist (" + scenario + "):\n- [ ] " + list.join("\n- [ ] ");
}

/** Summarize an expense ledger: category and month totals. */
export function summarizeLedger({ entries = [] } = {}) {
  const list = Array.isArray(entries) ? entries.filter((e) => e) : [];
  const rows = list.map((e, i) => {
    const amount = Number(e.amount);
    if (!Number.isFinite(amount)) throw new Error("local: ledger amount must be a number");
    return { date: String(e.date || ""), category: String(e.category || "other"), amount, note: String(e.note || "") };
  });
  const byCategory = {};
  const byMonth = {};
  for (const r of rows) {
    byCategory[r.category] = (byCategory[r.category] || 0) + r.amount;
    const month = r.date.slice(0, 7);
    if (month) byMonth[month] = (byMonth[month] || 0) + r.amount;
  }
  const total = rows.reduce((s, r) => s + r.amount, 0);
  const catRows = Object.entries(byCategory).sort((a, b) => b[1] - a[1]);
  const monthRows = Object.entries(byMonth).sort((a, b) => (a[0] < b[0] ? -1 : 1));
  const text = [
    "# Ledger summary",
    "",
    "Total: " + round2(total) + " (" + rows.length + " entries)",
    "",
    "## By category",
    "| Category | Amount |",
    "|----------|--------|",
    ...catRows.map(([k, v]) => "| " + k + " | " + round2(v) + " |"),
    "",
    "## By month",
    "| Month | Amount |",
    "|-------|--------|",
    ...monthRows.map(([k, v]) => "| " + k + " | " + round2(v) + " |"),
  ].join("\n");
  const obj = (o) => Object.fromEntries(Object.entries(o).map(([k, v]) => [k, round2(v)]));
  return { total: round2(total), count: rows.length, byCategory: obj(byCategory), byMonth: obj(byMonth), text };
}

/** Equal-payment (annuity) loan amortization schedule. */
export function amortize({ principal = 0, annualRate = 0, years = 0 } = {}) {
  const p = Number(principal);
  const r = Number(annualRate) / 100 / 12;
  const n = Math.floor(Number(years) * 12);
  if (!Number.isFinite(p) || p <= 0) throw new Error("local: principal must be a positive number");
  if (!Number.isFinite(n) || n <= 0) throw new Error("local: years must be positive");
  const payment = r > 0 ? (p * r * Math.pow(1 + r, n)) / (Math.pow(1 + r, n) - 1) : p / n;
  let balance = p;
  const schedule = [];
  for (let i = 1; i <= n; i++) {
    const interest = balance * r;
    const principalPart = payment - interest;
    balance -= principalPart;
    schedule.push({ no: i, payment: round2(payment), interest: round2(interest), principal: round2(principalPart), balance: round2(Math.max(0, balance)) });
  }
  const totalPayment = payment * n;
  const totalInterest = totalPayment - p;
  const text = [
    "# Loan schedule (equal payment)",
    "",
    "Principal: " + round2(p) + ", annual rate: " + Number(annualRate) + "%, term: " + years + " year(s)",
    "Monthly payment: " + round2(payment) + ", total payment: " + round2(totalPayment) + ", total interest: " + round2(totalInterest),
    "",
    "| # | Payment | Interest | Principal | Balance |",
    "|---|---------|----------|-----------|---------|",
    ...schedule.map((s) => "| " + s.no + " | " + s.payment + " | " + s.interest + " | " + s.principal + " | " + s.balance + " |"),
  ].join("\n");
  return { monthly: round2(payment), totalPayment: round2(totalPayment), totalInterest: round2(totalInterest), schedule, text };
}

/** Equal-principal loan amortization schedule. */
export function amortizeEqualPrincipal({ principal = 0, annualRate = 0, years = 0 } = {}) {
  const p = Number(principal);
  const r = Number(annualRate) / 100 / 12;
  const n = Math.floor(Number(years) * 12);
  if (!Number.isFinite(p) || p <= 0) throw new Error("local: principal must be a positive number");
  if (!Number.isFinite(n) || n <= 0) throw new Error("local: years must be positive");
  const principalPart = p / n;
  let balance = p;
  const schedule = [];
  for (let i = 1; i <= n; i++) {
    const interest = balance * r;
    const payment = principalPart + interest;
    balance -= principalPart;
    schedule.push({ no: i, payment: round2(payment), interest: round2(interest), principal: round2(principalPart), balance: round2(Math.max(0, balance)) });
  }
  const totalInterest = schedule.reduce((s, x) => s + x.interest, 0);
  const text = [
    "# Loan schedule (equal principal)",
    "",
    "Principal: " + round2(p) + ", annual rate: " + Number(annualRate) + "%, term: " + years + " year(s)",
    "Monthly principal: " + round2(principalPart) + ", total interest: " + round2(totalInterest),
    "",
    "| # | Payment | Interest | Principal | Balance |",
    "|---|---------|----------|-----------|---------|",
    ...schedule.map((s) => "| " + s.no + " | " + s.payment + " | " + s.interest + " | " + s.principal + " | " + s.balance + " |"),
  ].join("\n");
  return { monthlyPrincipal: round2(principalPart), totalInterest: round2(totalInterest), schedule, text };
}
/** Compare unit prices across products (spec-normalized). */
export function compareUnitPrices({ items = [], normalize = 1000, unit = "kg" } = {}) {
  const list = (Array.isArray(items) ? items : []).filter((x) => x && x.name);
  if (list.length === 0) throw new Error("local: at least one item with a name is required");
  const norm = Number(normalize) > 0 ? Number(normalize) : 1000;
  const rows = list.map((it) => {
    const price = Number(it.price);
    const qty = Number(it.quantity);
    if (!Number.isFinite(price) || price < 0) throw new Error("local: item price must be a non-negative number");
    if (!Number.isFinite(qty) || qty <= 0) throw new Error("local: item quantity must be positive");
    const perUnit = price / qty;
    return {
      name: String(it.name),
      price: round2(price),
      quantity: qty,
      unit: String(it.unit || unit),
      unitPrice: round2(perUnit),
      perNormalized: round2(perUnit * norm),
    };
  });
  const best = rows.reduce((a, b) => (b.perNormalized < a.perNormalized ? b : a));
  const worst = rows.reduce((a, b) => (b.perNormalized > a.perNormalized ? b : a));
  const savings = round2(worst.perNormalized - best.perNormalized);
  const savingsPct = worst.perNormalized > 0 ? round2((savings / worst.perNormalized) * 100) : 0;
  const text = [
    "# Unit price comparison (per " + norm + " " + unit + ")",
    "",
    "| Item | Price | Qty | Unit price | Per " + norm + " " + unit + " |",
    "|------|-------|-----|-----------|-------------------|",
    ...rows.map((r) => "| " + r.name + (r.name === best.name ? " (best)" : "") + " | " + r.price + " | " + r.quantity + " " + r.unit + " | " + r.unitPrice + " | " + r.perNormalized + " |"),
    "",
    "Best: " + best.name + " | worst: " + worst.name + " | save " + savings + " per " + norm + " " + unit + " (" + savingsPct + "%)",
  ].join("\n");
  return { rows, best: best.name, worst: worst.name, savings, savingsPct, normalizedTo: norm, unit, text };
}

/** Stack percentage / amount discounts (with optional thresholds). */
export function stackDiscounts({ price = 0, discounts = [] } = {}) {
  const start = Number(price);
  if (!Number.isFinite(start) || start < 0) throw new Error("local: price must be a non-negative number");
  const list = (Array.isArray(discounts) ? discounts : []).filter((d) => d && (d.pct !== undefined || d.amount !== undefined));
  if (list.length === 0) throw new Error("local: at least one discount with pct or amount is required");
  let current = start;
  const steps = [];
  list.forEach((d, i) => {
    const threshold = Number(d.threshold) || 0;
    const before = current;
    if (threshold > 0 && current < threshold) {
      steps.push({ index: i + 1, applied: false, reason: "below threshold " + threshold, threshold, before: round2(before), after: round2(before), saved: 0 });
      return;
    }
    let off = 0;
    if (d.pct !== undefined) {
      const pct = Number(d.pct);
      if (!Number.isFinite(pct) || pct < 0 || pct > 100) throw new Error("local: discount pct must be between 0 and 100");
      off = (current * pct) / 100;
    } else {
      const amt = Number(d.amount);
      if (!Number.isFinite(amt) || amt < 0) throw new Error("local: discount amount must be a non-negative number");
      off = amt;
    }
    off = Math.min(off, current);
    current = current - off;
    steps.push({ index: i + 1, applied: true, before: round2(before), after: round2(current), saved: round2(off) });
  });
  const totalSaved = round2(start - current);
  const effectivePct = start > 0 ? round2((totalSaved / start) * 100) : 0;
  const text = [
    "# Discount stack",
    "",
    "Start: " + round2(start) + " -> final: " + round2(current) + " | saved " + totalSaved + " (" + effectivePct + "%)",
    "",
    "| # | Applied | Before | After | Saved | Note |",
    "|---|---------|--------|-------|-------|------|",
    ...steps.map((s) => "| " + s.index + " | " + (s.applied ? "yes" : "no") + " | " + s.before + " | " + s.after + " | " + s.saved + " | " + (s.reason || "-") + " |"),
  ].join("\n");
  return { start: round2(start), final: round2(current), totalSaved, effectivePct, steps, text };
}

/** Recipe cost: ingredients x quantity x unit price -> per-serving and total. */
export function recipeCost({ name = "", servings = 1, ingredients = [] } = {}) {
  const list = (Array.isArray(ingredients) ? ingredients : []).filter((x) => x && x.name);
  if (list.length === 0) throw new Error("local: at least one ingredient is required");
  const srv = Number(servings);
  if (!Number.isFinite(srv) || srv <= 0) throw new Error("local: servings must be positive");
  const rows = list.map((it) => {
    const qty = Number(it.quantity);
    const unitPrice = Number(it.unitPrice);
    if (!Number.isFinite(qty) || qty < 0) throw new Error("local: ingredient quantity must be a non-negative number");
    if (!Number.isFinite(unitPrice) || unitPrice < 0) throw new Error("local: ingredient unit price must be a non-negative number");
    return { name: String(it.name), quantity: qty, unit: String(it.unit || ""), unitPrice: round2(unitPrice), cost: round2(qty * unitPrice) };
  });
  const total = round2(rows.reduce((a, b) => a + b.cost, 0));
  const perServing = round2(total / srv);
  const text = [
    "# Recipe cost" + (name ? ": " + name : ""),
    "",
    "| Ingredient | Qty | Unit price | Cost |",
    "|------------|-----|-----------|------|",
    ...rows.map((r) => "| " + r.name + " | " + r.quantity + (r.unit ? " " + r.unit : "") + " | " + r.unitPrice + " | " + r.cost + " |"),
    "",
    "Total: " + total + " | servings: " + srv + " | per serving: " + perServing,
  ].join("\n");
  return { rows, total, servings: srv, perServing, text };
